from pathlib import Path
import base64
def put(path,data):
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(data,encoding="utf-8")
def putb(path,data):
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(data))
ICONS={'mdpi': '', 'hdpi': '', 'xhdpi': '', 'xxhdpi': '', 'xxxhdpi': ''}
for density,data in ICONS.items():
    putb("app/src/main/res/mipmap-"+density+"/ic_launcher.png",data)
    putb("app/src/main/res/mipmap-"+density+"/ic_launcher_round.png",data)
putb("app/src/main/res/drawable/situsnap_splash_mark.png",'')
putb("app/src/main/res/drawable/situsnap_mountain_splash.jpg", '')
put("app/src/main/res/drawable/situsnap_splash_bg.xml", """<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle"><gradient android:startColor="#061827" android:endColor="#003C42" android:angle="135"/></shape>""")
put("app/src/main/res/values/colors.xml", """<resources><color name="situsnap_green">#39E66C</color></resources>""")
put("app/src/main/res/values/styles.xml", """<resources>
<style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar"><item name="android:fontFamily">sans</item><item name="android:windowLightStatusBar">false</item><item name="android:statusBarColor">#061827</item><item name="android:navigationBarColor">#061827</item><item name="android:windowBackground">@drawable/situsnap_splash_bg</item><item name="android:colorAccent">#39E66C</item></style>
<style name="SplashTheme" parent="android:style/Theme.Material.Light.NoActionBar"><item name="android:fontFamily">sans</item><item name="android:windowLightStatusBar">false</item><item name="android:statusBarColor">#061827</item><item name="android:navigationBarColor">#061827</item><item name="android:windowBackground">@drawable/situsnap_splash_bg</item><item name="android:colorAccent">#39E66C</item></style>
</resources>""")
put("app/src/main/java/com/situsnap/app/SplashActivity.java", """package com.situsnap.app;
import android.app.Activity; import android.content.Intent; import android.os.*; import android.view.*; import android.widget.*;
public class SplashActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);
  ImageView splash=new ImageView(this);
  splash.setImageResource(R.drawable.situsnap_mountain_splash);
  splash.setScaleType(ImageView.ScaleType.CENTER_CROP);
  splash.setBackgroundColor(android.graphics.Color.rgb(6,24,39));
  setContentView(splash);
  new Handler(getMainLooper()).postDelayed(()->{startActivity(new Intent(this,MainActivity.class));finish();},2000);
 }
}
""")
manifest=Path("app/src/main/AndroidManifest.xml")
m=manifest.read_text(encoding="utf-8")
m=m.replace('<application android:theme="@style/AppTheme" android:label="SituSnap" android:usesCleartextTraffic="false">','<application android:theme="@style/AppTheme" android:label="SituSnap" android:icon="@mipmap/ic_launcher" android:roundIcon="@mipmap/ic_launcher_round" android:usesCleartextTraffic="false">')
m=m.replace('<activity android:name=".MainActivity" android:exported="true">\n<intent-filter>\n<action android:name="android.intent.action.MAIN"/>\n<category android:name="android.intent.category.LAUNCHER"/>\n</intent-filter>\n</activity>','<activity android:name=".SplashActivity" android:theme="@style/SplashTheme" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity>\n<activity android:name=".MainActivity" android:exported="false"/>')
manifest.write_text(m,encoding="utf-8")
main=Path("app/src/main/java/com/situsnap/app/MainActivity.java")
j=main.read_text(encoding="utf-8")
if "import android.graphics.Color;" not in j: j=j.replace("import android.content.ContentValues;","import android.content.ContentValues;\nimport android.graphics.Color;")
needle="webView = new WebView(this);\n        setContentView(webView);"
if needle not in j: raise SystemExit("MainActivity anchor changed; refusing unsafe patch.")
j=j.replace(needle,"webView = new WebView(this);\n        webView.setBackgroundColor(Color.rgb(6,24,39));\n        setContentView(webView);",1)
main.write_text(j,encoding="utf-8")
print("Approved SituSnap raster branding installed; no loading bar; engine untouched.")
